package com.netec.exams.notification;
import java.time.Instant; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component class NotificationWorker {private final NotificationOutboxRepository repo;private final ApprovalNotificationSender sender;NotificationWorker(NotificationOutboxRepository repo,ApprovalNotificationSender sender){this.repo=repo;this.sender=sender;}@Scheduled(fixedDelayString="${app.notifications.poll-interval-ms:30000}")void process(){for(var n:repo.findTop20ByStatusAndNextAttemptAtLessThanEqualOrderByCreatedAtAsc("PENDING",Instant.now()))processOne(n.id());}@Transactional void processOne(java.util.UUID id){var n=repo.findById(id).orElse(null);if(n==null||"SENT".equals(n.status()))return;try{sender.send(n);n.sent(Instant.now());}catch(Exception ex){n.failed(ex.getClass().getSimpleName(),Instant.now());}repo.save(n);}}
